INF = float('inf')

def floyd_warshall(n, edges):
    d = [[INF] * n for _ in range(n)]
    for i in range(n):
        d[i][i] = 0
    for u, v, w in edges:  # 직접 간선 가중치로 초기화
        d[u][v] = min(d[u][v], w)
    for k in range(n):  # 경유 정점 k를 하나씩 추가
        for i in range(n):
            for j in range(n):
                if d[i][k] + d[k][j] < d[i][j]:
                    d[i][j] = d[i][k] + d[k][j]
    if any(d[i][i] < 0 for i in range(n)):
        raise ValueError('음수 사이클 존재')
    return d

