class Glyph:  # 플라이웨이트: 내재 상태(문자 모양)만 보유
    def __init__(self, char):
        self.char = char

    def draw(self, x, y, color):  # 외재 상태는 인자로 전달
        render(self.char, x, y, color)

class GlyphFactory:  # 공유 객체 풀 관리
    _pool = {}

    @classmethod
    def get(cls, char):
        if char not in cls._pool:  # 없을 때만 생성
            cls._pool[char] = Glyph(char)
        return cls._pool[char]

for i, ch in enumerate('hello'):
    GlyphFactory.get(ch).draw(i * 10, 0, 'black')
# 'l'은 두 번 쓰이지만 Glyph 객체는 1개만 생성
